export default function Contact() {
  const links = [
    { label: 'Facebook', url: 'https://www.facebook.com/clareny' },
    { label: 'Instagram', url: 'https://www.instagram.com/clarenymusic' },
    { label: 'TikTok', url: 'https://www.tiktok.com/@clarenymusic' },
    { label: 'YouTube', url: 'https://www.youtube.com/c/clareny' },
    { label: 'Beats YouTube', url: 'https://www.youtube.com/@clarenyonthetrack' },
    { label: 'Spotify', url: 'https://open.spotify.com/artist/1kS2GOJRVZeWbgeuNrdpaE' },
  ];

  return (
    <section id="contact" className="contact-section">
      <h2 className="section-title">Contacto</h2>
      <p className="contact-copy">
        Si querés trabajar conmigo, mandame WhatsApp con lo que necesitás y te respondo con una propuesta acorde a la idea. También podés reservar una videollamada por Discord para hablar ideas, escuchar referencias y definir el proyecto.
      </p>

      <div className="social-links">
        {links.map((link) => (
          <a key={link.label} href={link.url} target="_blank" rel="noreferrer">
            {link.label}
          </a>
        ))}
      </div>

      <div className="contact-grid">
        <a className="btn btn-primary" href="https://wa.me/59897989368" target="_blank" rel="noreferrer">Enviar WhatsApp</a>
        <a className="btn btn-secondary" href="https://calendar.app.google/d58w7kzfTmrHnQ8z9" target="_blank" rel="noreferrer">Ver disponibilidad</a>
        <a className="btn btn-secondary" href="https://discord.gg/gN4dTZ2rJ" target="_blank" rel="noreferrer">Entrar a Discord</a>
      </div>

      <div className="teaser-box">
        <p>Los precios se ajustan según el proyecto, la complejidad y el alcance del trabajo. Escribime y te paso una propuesta acorde a lo que necesitás.</p>
      </div>
    </section>
  );
}
